#!/usr/bin/env bash
set -euo pipefail
# Cole e rode no terminal do Linux Mint (host Coolify), com sudo.
CERT_DIR=/data/coolify/proxy/certs
DYN_DIR=/data/coolify/proxy/dynamic
sudo install -d -m 700 "$CERT_DIR" "$DYN_DIR"
echo '' | base64 -d | sudo tee "$CERT_DIR/gesint.local.crt" >/dev/null
echo '' | base64 -d | sudo tee "$CERT_DIR/gesint.local.key" >/dev/null
sudo chmod 600 "$CERT_DIR/gesint.local.key"
sudo chmod 644 "$CERT_DIR/gesint.local.crt"
sudo tee "$DYN_DIR/gesint-lab-certs.yaml" >/dev/null <<'EOF'
tls:
  certificates:
    - certFile: /traefik/certs/gesint.local.crt
      keyFile: /traefik/certs/gesint.local.key
EOF
# Reinicia o proxy Coolify
if docker ps --format '{{.Names}}' | grep -q '^coolify-proxy$'; then
  sudo docker restart coolify-proxy
  echo 'coolify-proxy reiniciado.'
else
  echo 'Container coolify-proxy nao encontrado; reinicie o Proxy pelo Coolify UI.'
fi
echo 'Pronto. No Windows (Admin): Importe a CA e reabra o Chrome.'
